export function createIngestionCheckpoint() {
    return {
        phase: "inventory",
        cursor: null,
        inventoryComplete: false,
        itemOffset: 0,
        itemsInventoried: 0,
        itemsProcessed: 0,
        itemsFailed: 0,
    };
}
export function acquireIngestionLease(current, input) {
    const now = input.now ?? Date.now();
    if (current && current.expiresAt > now && current.owner !== input.owner) {
        return { acquired: false, lease: current };
    }
    const ttlMs = positiveInteger(input.ttlMs, "lease ttlMs");
    return {
        acquired: true,
        lease: {
            owner: nonEmpty(input.owner, "lease owner"),
            token: nonEmpty(input.token, "lease token"),
            acquiredAt: now,
            expiresAt: now + ttlMs,
        },
    };
}
export function renewIngestionLease(current, input) {
    if (current.token !== input.token)
        return null;
    const now = input.now ?? Date.now();
    if (current.expiresAt <= now)
        return null;
    return {
        ...current,
        expiresAt: now + positiveInteger(input.ttlMs, "lease ttlMs"),
    };
}
export function releaseIngestionLease(current, token) {
    if (!current || current.token === token)
        return null;
    return current;
}
export function createIngestionBudgetState(now = Date.now()) {
    return { startedAt: now, items: 0, batches: 0 };
}
export function consumeIngestionBudget(state, input) {
    return {
        ...state,
        items: state.items + nonNegativeInteger(input.items ?? 0, "items"),
        batches: state.batches + nonNegativeInteger(input.batches ?? 0, "batches"),
    };
}
export function ingestionBudgetStopReason(limits, state, now = Date.now()) {
    if (now - state.startedAt >= positiveInteger(limits.runtimeMs, "runtimeMs")) {
        return "runtime";
    }
    if (state.items >= positiveInteger(limits.itemBudget, "itemBudget")) {
        return "items";
    }
    if (state.batches >= positiveInteger(limits.batchBudget, "batchBudget")) {
        return "batches";
    }
    return null;
}
export function assertInventoryComplete(checkpoint) {
    if (!checkpoint.inventoryComplete) {
        throw new Error("Context import fetch cannot start before inventory is complete.");
    }
}
function nonEmpty(value, name) {
    const normalized = value.trim();
    if (!normalized)
        throw new Error(`${name} is required.`);
    return normalized;
}
function positiveInteger(value, name) {
    if (!Number.isInteger(value) || value <= 0) {
        throw new Error(`${name} must be a positive integer.`);
    }
    return value;
}
function nonNegativeInteger(value, name) {
    if (!Number.isInteger(value) || value < 0) {
        throw new Error(`${name} must be a non-negative integer.`);
    }
    return value;
}
